// Prepare AI Prompt with Shop Knowledge and Product Catalog
const input = $input.first().json;

const shop = input.tenant || {};
const customer = input.customer || {};
const catalog = input.catalog || [];

const catalogText = catalog.map((p, i) => 
  `${i + 1}. [ID: ${p.id}] ${p.title} - মূল্য: ৳${p.price} | স্টক: ${p.stock} | বিবরণ: ${p.description || 'N/A'}`
).join('\n');

const systemPrompt = `
তুমি হলে "${shop.name || 'KothaShop Partner'}"-এর অত্যন্ত চটপটে, বিনয়ী ও বিশ্বস্ত এআই সেলস ম্যানেজার।

[শপ সম্পর্কিত তথ্য]:
- পরিচিতি: ${shop.about_shop || 'একটি প্রিমিয়াম অনলাইন শপ'}
- ডেলিভারি চার্জ: ঢাকার ভেতর ৳${shop.delivery_inside_dhaka || 80}, ঢাকার বাইরে ৳${shop.delivery_outside_dhaka || 130}
- ডেলিভারি সময়: ঢাকা ${shop.delivery_time_dhaka || '১-২ কর্মদিবস'}, বাইরে ${shop.delivery_time_outside || '৩-৫ কর্মদিবস'}
- রিটার্ন পলিসি: ${shop.return_policy || '৭ দিনের রিটার্ন পলিসি'}
- হটলাইন: ${shop.support_phone || '০১৭০০০০০০০০'}
- বিশেষ নিয়ম: ${shop.custom_rules || 'কোনো নিয়ম নেই'}

[পণ্য ক্যাটালগ]:
${catalogText}

[কাস্টমারের মেসেজ]: "${customer.raw_message}"

[তোমার করণীয়]:
১. কাস্টমার সাধারণ পণ্যের দাম, কালার বা ডেলিভারি জানতে চাইলে আন্তরিক বাংলায় সুন্দরভাবে উত্তর দাও।
২. কাস্টমার যদি পণ্য অর্ডার করতে চায়, তবে তার নাম, ফোন নম্বর, বিস্তারিত ঠিকানা ও ডেলিভারি সিটি (ঢাকা নাকি ঢাকার বাইরে) সংগ্রহ করো।
৩. যদি নাম, সঠিক ১১ ডিজিটের মোবাইল নম্বর এবং ঠিকানা পাওয়া যায়, তবে অর্ডারটি কনফার্ম করো এবং নিশ্চিতকরণ বার্তা দাও।

[আউটপুট ফরম্যাট - শুধুমাত্র একটি বৈধ JSON রিটার্ন করবে]:
{
  "reply_text": "কাস্টমারকে পাঠানোর মতো মিষ্টি ও আন্তরিক বাংলা বার্তা",
  "is_order_confirmed": true/false,
  "order_details": {
    "customer_name": "গ্রাহকের নাম",
    "customer_phone": "মোবাইল নম্বর",
    "delivery_address": "পূর্ণ ঠিকানা",
    "delivery_city": "Dhaka অথবা Outside Dhaka",
    "product_title": "অর্ডারকৃত পণ্যের নাম",
    "quantity": 1,
    "unit_price": 1200,
    "delivery_fee": 80,
    "total_amount": 1280
  }
}
`;

return {
  json: {
    ...input,
    prepared_system_prompt: systemPrompt,
    customer_query: customer.raw_message,
  }
};

// Parse Gemini AI structured JSON output
const geminiRes = $input.first().json;
const prev = $('2. Context & Prompt Builder').first().json;

let aiOutput = {};
try {
  const rawText = geminiRes.candidates[0].content.parts[0].text;
  aiOutput = JSON.parse(rawText);
} catch (e) {
  aiOutput = {
    reply_text: 'ধন্যবাদ আপনার মেসেজের জন্য! আমাদের শপ ম্যানেজার শীঘ্রই যোগাযোগ করবে।',
    is_order_confirmed: false,
  };
}

const isConfirmed = !!aiOutput.is_order_confirmed;

return {
  json: {
    event_id: prev.event_id,
    tenant_id: prev.tenant?.id,
    channel_id: prev.channel?.id,
    page_id: prev.channel?.page_id,
    sender_id: prev.customer?.sender_id,
    page_access_token: prev.channel?.page_access_token,
    callback_url: prev.callback_url || 'http://localhost:3001/api/n8n/callback',
    reply_text: aiOutput.reply_text || '',
    is_order_confirmed: isConfirmed,
    order_data: isConfirmed ? {
      customer_name: aiOutput.order_details?.customer_name,
      customer_phone: aiOutput.order_details?.customer_phone,
      delivery_address: aiOutput.order_details?.delivery_address,
      delivery_city: aiOutput.order_details?.delivery_city || 'Dhaka',
      delivery_fee: aiOutput.order_details?.delivery_fee || 80,
      subtotal: (aiOutput.order_details?.unit_price || 0) * (aiOutput.order_details?.quantity || 1),
      total_amount: aiOutput.order_details?.total_amount,
      items: [
        {
          title: aiOutput.order_details?.product_title || 'পণ্য',
          quantity: aiOutput.order_details?.quantity || 1,
          unit_price: aiOutput.order_details?.unit_price || 0,
        }
      ]
    } : null
  }
};
